	{"\tt.Parent = parent\n\tBrickUI.stroke(t, th or 0.07)\n\treturn t\nend", "\tt.Parent = parent\n\tif CUI then\n\t\t-- (2026-10-22 UI polish, M6-A) the outline is pure black and never thinner than 2.5 px at the 1050 x 620 base (the\n\t\t-- Check-UI canon is 2.6-3.5 px): small labels on lime / silver / gold / cyan keep a readable edge (black outline\n\t\t-- vs lime 12.4:1, vs cyan 5.1:1; white fill vs outline 21:1). Big labels keep their ScaledSize share as before.\n\t\tBrickUI.minOutline(t, BrickUI.stroke(t, th or 0.07, Color3.new(0, 0, 0)), th or 0.07)\n\telse\n\t\tBrickUI.stroke(t, th or 0.07)\n\tend\n\treturn t\nend", 504195812, 2041658549},
	{"function BrickUI.text(parent, name, font, color, size, pos, th, anchor)", "-- (2026-10-22 UI polish, M6-A) minOutline(label, stroke, th): the ScaledSize stroke th (a share of the label's shorter\n-- side) is raised to at least MIN_OUTLINE base px, re-checked when the label's size changes (event-driven, nothing per\n-- frame). A script that sets the stroke's Thickness itself keeps its value as the new share.\nBrickUI.MIN_OUTLINE = 2.5\nlocal function outlineScale()\n\tlocal vp = BrickUI.viewportSize()\n\tif not viewportReady(vp) then return 1 end\n\treturn math.max(0.52, math.min(vp.X / 1050, vp.Y / 620))\nend\nfunction BrickUI.minOutline(t, s, th)\n\tif not IS_CLIENT then return s end\n\tlocal base, writing = th, false\n\tlocal function fit()\n\t\tlocal a = t.AbsoluteSize\n\t\tlocal m = math.min(a.X, a.Y)\n\t\tif m <= 0 then return end\n\t\twriting = true\n\t\ts.Thickness = math.max(base, BrickUI.MIN_OUTLINE * outlineScale() / m)\n\t\twriting = false\n\tend\n\ts:GetPropertyChangedSignal(\"Thickness\"):Connect(function() if not writing then base = s.Thickness fit() end end)\n\tt:GetPropertyChangedSignal(\"AbsoluteSize\"):Connect(fit)\n\tfit()\n\treturn s\nend\n\nfunction BrickUI.text(parent, name, font, color, size, pos, th, anchor)", 3443370037, 2733294010},
	{"------------------------------------------------------------------ HATCH NIGHT window skin (2026-10-21)", "------------------------------------------------------------------ (2026-10-22 UI polish, M7) tap areas\n-- tapArea(button, onActivate, minPx): an invisible TextButton BEHIND the button (a sibling, ZIndex - 1), centred on it,\n-- never smaller than minPx x minPx SCREEN px (default 44 = 44 pt on a phone). Taps on the button itself still reach the\n-- button (its press / hover feel stays); taps on the extension call onActivate. Follows the button's size, position\n-- and visibility. Works under any UIScale (the size is a factor of the button's own UDim2).\nfunction BrickUI.tapArea(button, onActivate, minPx)\n\tminPx = minPx or 44\n\tlocal hit = Instance.new(\"TextButton\")\n\thit.Name = button.Name .. \"TapArea\"\n\thit.Text = \"\"\n\thit.BackgroundTransparency = 1\n\thit.AutoButtonColor = false\n\thit.Selectable = false\n\thit.AnchorPoint = button.AnchorPoint\n\thit.ZIndex = math.max(1, button.ZIndex - 1)\n\tlocal ar = button:FindFirstChildOfClass(\"UIAspectRatioConstraint\")\n\tif ar then ar:Clone().Parent = hit end\n\tlocal function fit()\n\t\tlocal a = button.AbsoluteSize\n\t\thit.Visible = button.Visible\n\t\thit.Position = button.Position\n\t\thit.Rotation = button.Rotation\n\t\tif a.X <= 0 or a.Y <= 0 then return end\n\t\tlocal s = button.Size\n\t\tlocal fx, fy = math.max(1, minPx / a.X), math.max(1, minPx / a.Y)\n\t\thit.Size = UDim2.new(s.X.Scale * fx, s.X.Offset * fx, s.Y.Scale * fy, s.Y.Offset * fy)\n\tend\n\tfor _, prop in {\"AbsoluteSize\", \"Position\", \"Visible\", \"Size\"} do button:GetPropertyChangedSignal(prop):Connect(fit) end\n\thit.Activated:Connect(function() onActivate() end)\n\thit.Parent = button.Parent\n\tfit()\n\treturn hit\nend\n\n------------------------------------------------------------------ HATCH NIGHT window skin (2026-10-21)", 1258181443, 4071975858},
})
